<template>
  <main class="document-page" :aria-busy="busy">
    <header><div><h1>受控技术文档</h1><p>登记原件、派生关系和文档修订，保留每份内容的准确版本。</p></div><button :disabled="busy" @click="reload">刷新</button></header>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
    <section v-if="pending"><h2>原操作待确认</h2><p>请先查询原结果，再继续修改。</p><button :disabled="busy" @click="recover(false)">查询原操作</button><button :disabled="busy" @click="recover(true)">结束未提交操作</button></section>
    <section v-if="canRead"><h2>工程来源</h2><form @submit.prevent="findParents(1)"><label>工程修订搜索<input v-model="search" aria-label="工程修订搜索" :disabled="busy" /></label><button :disabled="busy">查找工程修订</button></form><button v-if="moreParents" :disabled="busy" @click="findParents(parentPage + 1)">更多工程修订</button>
      <label>工程修订<select v-model="choice" aria-label="工程修订选择" :disabled="locked"><option value="">请选择</option><option v-for="p in parents" :key="key(p.reference)" :value="key(p.reference)">{{ p.revisionCode }} · v{{ p.reference.version }} · {{ p.draft.goal }}</option></select></label><button :disabled="locked || !parent" @click="loadPage(1)">读取文档</button>
    </section>
    <section v-if="parent"><h2>文档目录</h2><button v-if="permissions.has('plm-controlled-document:add')" :disabled="locked || !parent.draft.productRef" @click="create">登记文档</button><p v-if="!rows.length">当前范围内没有文档。</p><article v-for="row in rows" :key="row.reference.id"><h3>{{ row.body.name }}</h3><p>修订 {{ row.body.revisionLabel }} · 工作版本 {{ row.reference.version }} · 待专业评审</p><button :disabled="busy" @click="open(row.reference.id)">查看文档</button></article><nav><button :disabled="busy || page === 1" @click="loadPage(page - 1)">上一页</button><span>第 {{ page }} 页</span><button :disabled="busy || rows.length < 20" @click="loadPage(page + 1)">下一页</button></nav></section>
    <section v-if="body"><h2>{{ current ? '修订文档资料' : '登记原始资料' }}</h2><p>保存的是待评审修订。来源、语言权威和派生依据按实际资料填写；未知项可留空，批准与用途许可另行确认。</p>
      <form @submit.prevent="save"><fieldset :disabled="locked || !canWrite"><div class="grid"><label>文档名称<input v-model="body.name" aria-label="文档名称" maxlength="4000" required /></label><label>修订标记<input v-model="body.revisionLabel" aria-label="修订标记" maxlength="4000" required /></label>
        <label>来源类别<select v-model="body.source.kind" aria-label="来源类别"><option value="INTERNAL">内部编制</option><option value="EXTERNAL">外来文档</option></select></label><label>原始 Owner<input v-model="body.source.ownerName" aria-label="原始 Owner" /></label><label>来源单位<input v-model="body.source.organization" aria-label="来源单位" /></label><label>来源版本<input v-model="body.source.sourceVersion" aria-label="来源版本" /></label><label>来源日期<input v-model="body.source.sourceDate" aria-label="来源日期" type="date" /></label><label>取得依据<textarea v-model="body.source.acquisitionBasis" aria-label="取得依据" /></label><label>权威语言<input v-model="body.source.authorityLanguage" aria-label="权威语言" /></label><label>语言权威依据<textarea v-model="body.source.authorityBasis" aria-label="语言权威依据" /></label></div>
        <h3>准确内容与派生关系</h3><p>从当前工程的文件目录选择已经检查的原件；未上传的内容可先在“受控文件内容”入口保存。</p><button type="button" @click="loadFiles(1)">读取可选文件</button><button v-if="moreFiles" type="button" @click="loadFiles(filePage + 1)">更多文件</button><label>文件版本<select v-model="fileChoice" aria-label="文件版本"><option value="">请选择</option><option v-for="f in available" :key="f.contentRef.id" :value="f.contentRef.id" :disabled="f.availability !== 'AVAILABLE'">{{ f.fileName }} · {{ f.contentRef.digest.slice(0, 12) }} · {{ availability(f.availability) }}</option></select></label><button type="button" :disabled="!fileChoice" @click="addContent">加入内容</button>
        <article v-for="(item, index) in body.contents" :key="item.occurrenceId"><h4>{{ fileName(item) }}</h4><p class="digest">SHA256：{{ item.file.digest }}</p><div class="grid"><label>内容角色<select v-model="item.role" :aria-label="`内容角色 ${index + 1}`" @change="roleChanged(item)"><option value="SOURCE">原始文件</option><option value="CONTROLLED">受控正文</option><option value="PREVIEW">预览派生件</option><option value="TRANSLATION">翻译件</option></select></label><label>内容语言<input v-model="item.language" :aria-label="`内容语言 ${index + 1}`" /></label>
          <template v-if="derived(item)"><label>派生自<select v-model="item.derivedFromOccurrenceId" :aria-label="`派生来源 ${index + 1}`" required><option :value="null">请选择准确原件</option><option v-for="source in body.contents.filter(x => !derived(x) && x.occurrenceId !== item.occurrenceId)" :key="source.occurrenceId" :value="source.occurrenceId">{{ fileName(source) }} · {{ source.file.digest.slice(0, 12) }}</option></select></label><label>派生依据<textarea v-model="item.derivationBasis" :aria-label="`派生依据 ${index + 1}`" required /></label></template></div><button type="button" @click="removeContent(item)">移除此内容</button></article>
        <label>修订原因<textarea v-model="reason" aria-label="修订原因" maxlength="4000" required /></label><button :disabled="!body.contents.length">保存文档修订</button>
      </fieldset></form>
    </section>
    <section v-if="current"><h2>已保存版本</h2><p>{{ current.body.name }} · v{{ current.reference.version }} · {{ current.reason }}</p><ul><li v-for="item in current.contentStatus" :key="item.occurrenceId">{{ item.fileName }}：{{ availability(item.availability) }} <button :disabled="busy || item.availability !== 'AVAILABLE'" @click="download(current, item.occurrenceId)">下载准确内容</button></li></ul><p v-if="current.missing.length">{{ current.missing.map(finding).join('；') }}</p>
      <form @submit.prevent="readHistory"><label>历史工作版本<input v-model="historyVersion" aria-label="历史工作版本" pattern="[1-9][0-9]*" required /></label><button :disabled="busy">读取历史</button></form>
      <article v-if="history"><h3>历史 v{{ history.reference.version }} · {{ history.body.name }}</h3><p>历史引用保持原版本。下载仍核对当前权限与安全状态。</p><ul><li v-for="item in history.contentStatus" :key="item.occurrenceId">{{ item.fileName }}：{{ availability(item.availability) }} <button :disabled="busy || item.availability !== 'AVAILABLE'" @click="download(history, item.occurrenceId)">下载历史内容</button></li></ul></article>
      <form @submit.prevent="readDiff"><label>比较起始版本<input v-model="before" aria-label="比较起始版本" pattern="[1-9][0-9]*" /></label><label>比较结束版本<input v-model="after" aria-label="比较结束版本" pattern="[1-9][0-9]*" /></label><button :disabled="busy">比较版本</button></form><ul v-if="diff"><li v-for="change in diff.changes" :key="change.path">{{ change.path.startsWith('contents/') ? '内容或派生关系' : ({ name: '名称', source: '来源资料', revisionLabel: '修订标记', revisionOrigin: '工程来源', productRef: '产品来源' }[change.path] ?? '文档资料') }}：{{ display(change.before) }} → {{ display(change.after) }}</li></ul>
    </section>
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { documentApi, type DocumentBody, type DocumentContent, type DocumentSnapshot } from '@/api/plm/controlledDocument'
import { revisionApi, type RevisionDiff, type RevisionSnapshot } from '@/api/plm/engineeringRevisions'
import { fileContentApi, type FileSnapshot } from '@/api/pub/fileContent'
import type { EngineeringReference, EngineeringScope } from '@/api/plm/engineeringProducts'
import { pendingDocument, documentResponse as result, saveDocument, resolveDocument, type PendingDocument } from '@/auth/documentRecovery'
import { AUTH_EVENT, identityStamp, requireIdentity } from '@/auth/identity'
import { authenticationCanRead } from '@/auth/browserAuthentication'
import { usePermissionStore } from '@/stores/permission'
const permissions = usePermissionStore(), canRead = computed(() => permissions.loaded && permissions.has('plm-controlled-document:query'))
const busy = ref(false), error = ref(''), notice = ref(''), scope = ref<EngineeringScope | null>(null), pending = ref<PendingDocument | null>(null), locked = computed(() => busy.value || !!pending.value)
const parents = ref<RevisionSnapshot[]>([]), choice = ref(''), search = ref(''), parentPage = ref(1), moreParents = ref(false), parent = computed(() => parents.value.find(p => key(p.reference) === choice.value))
const rows = ref<DocumentSnapshot[]>([]), page = ref(1), current = ref<DocumentSnapshot | null>(null), history = ref<DocumentSnapshot | null>(null), body = ref<DocumentBody | null>(null), draftId = ref(''), reason = ref('')
const available = ref<FileSnapshot[]>([]), fileChoice = ref(''), filePage = ref(1), moreFiles = ref(false), historyVersion = ref('1'), before = ref('1'), after = ref('1'), diff = ref<RevisionDiff | null>(null)
const canWrite = computed(() => canRead.value && permissions.has(current.value ? 'plm-controlled-document:edit' : 'plm-controlled-document:add'))
let generation = 0, live = true; const urls = new Set<string>(), copy = <T,>(v: T): T => JSON.parse(JSON.stringify(v)), key = (r: EngineeringReference) => `${r.owner}:${r.id}:${r.version}:${r.digest}`
const derived = (v: DocumentContent) => v.role === 'PREVIEW' || v.role === 'TRANSLATION'
const availability = (v: string) => ({ AVAILABLE: '可申请下载', HELD: '保留中', QUARANTINED: '隔离中', PENDING_INSPECTION: '等待安全检查' }[v] ?? '内容暂不可用')
const finding = (v: string) => v.startsWith('CONTENT_UNAVAILABLE:') ? '存在当前不可用内容' : ({ DOCUMENT_PROFESSIONAL_REVIEW_REQUIRED: '待专业评审', SOURCE_EVIDENCE_INCOMPLETE: '来源资料待补充', LANGUAGE_AUTHORITY_UNRESOLVED: '权威语言待确认', LANGUAGE_AUTHORITY_REVIEW_REQUIRED: '语言权威依据待评审', CONTENT_LANGUAGE_UNRESOLVED: '内容语言待补充', PRODUCT_SOURCE_CHANGED: '产品来源已变化' }[v] ?? '尚有待确认事项')
const fileName = (v: DocumentContent) => available.value.find(x => x.contentRef.id === v.file.id)?.fileName ?? current.value?.contentStatus.find(x => x.occurrenceId === v.occurrenceId)?.fileName ?? '已固定内容'
const display = (value: unknown) => typeof value === 'string' ? value : value == null ? '未设置' : '结构化资料已变更'
function clearEditor() { current.value = history.value = null; body.value = null; diff.value = null; available.value = []; fileChoice.value = ''; draftId.value = reason.value = ''; moreFiles.value = false; for (const url of urls) URL.revokeObjectURL(url); urls.clear() }
function clearPrivate() { clearEditor(); rows.value = []; parents.value = []; choice.value = search.value = '' }
function syncPending() { pending.value = scope.value ? pendingDocument(scope.value) : null }
async function run(action: (check: () => void) => Promise<void>) {
  if (busy.value) return; const stamp = identityStamp(), epoch = generation
  const check = () => { requireIdentity(stamp); if (!live || generation !== epoch || !authenticationCanRead() || !canRead.value) throw new Error('当前身份或权限已变化。') }
  busy.value = true; error.value = notice.value = ''
  try { check(); await action(check); check() }
  catch (e: any) { try { check(); const status = e?.response?.status; if ([401, 403].includes(status)) clearPrivate(); error.value = [401, 403].includes(status) ? '当前无权读取文档或其原始内容。' : status === 412 ? '来源或文档版本已变化，请查询原操作并刷新。' : [409, 503].includes(status) ? '内容状态或派生依据不满足本次操作，请核对准确原件。' : e?.message || '操作结果尚未确认。' } catch { /* No stale identity disclosure. */ } }
  finally { try { check(); syncPending(); busy.value = false } catch { if (live && epoch === generation) busy.value = false } }
}
async function reload() { if (!permissions.loaded) await permissions.loadMyActions(); await run(async check => { clearPrivate(); scope.value = null; const s = result(await documentApi.scope()); check(); scope.value = s }) }
async function findParents(target: number) { const text = search.value; await run(async check => { if (target === 1) { clearEditor(); rows.value = []; parents.value = []; choice.value = '' } const values = result(await revisionApi.list(text, target)); check(); parents.value.push(...values.filter(v => v.isCurrent)); parentPage.value = target; moreParents.value = values.length === 20 }) }
async function loadRows(target: number, check: () => void) { const p = parent.value; if (!p) return; rows.value = []; const values = result(await documentApi.list(p.reference.id, '', target)); check(); if (values.some(v => v.tenantId !== scope.value?.tenantId || v.body.revisionOrigin.id !== p.reference.id)) throw new Error('文档上下文不一致。'); rows.value = values; page.value = target }
async function loadPage(target: number) { await run(check => loadRows(target, check)) }
function create() { const p = parent.value; if (!p?.draft.productRef || locked.value) return; clearEditor(); draftId.value = crypto.randomUUID(); body.value = { name: '', revisionLabel: '', revisionOrigin: copy(p.reference), productRef: copy(p.draft.productRef), source: { kind: 'INTERNAL', ownerName: '', organization: '', sourceVersion: '', sourceDate: null, acquisitionBasis: '', authorityLanguage: '', authorityBasis: '' }, contents: [] } }
async function open(id: string) { await run(async check => { clearEditor(); const v = result(await documentApi.read(id)); check(); if (v.tenantId !== scope.value?.tenantId || v.body.revisionOrigin.id !== parent.value?.reference.id) throw new Error('文档上下文已变化。'); current.value = v; body.value = copy(v.body); draftId.value = v.reference.id }) }
async function loadFiles(target: number) { const p = parent.value; if (!p) return; await run(async check => { if (target === 1) { available.value = []; fileChoice.value = '' } const values = result(await fileContentApi.list(p.reference.id, target)); check(); if (values.some(v => v.tenantId !== scope.value?.tenantId || v.parent.id !== p.reference.id)) throw new Error('文件上下文不一致。'); available.value.push(...values); filePage.value = target; moreFiles.value = values.length === 20 }) }
function addContent() { const file = available.value.find(f => f.contentRef.id === fileChoice.value); if (!body.value || !file || file.availability !== 'AVAILABLE' || body.value.contents.some(x => x.file.id === file.contentRef.id)) return; body.value.contents.push({ occurrenceId: crypto.randomUUID(), role: 'SOURCE', file: copy(file.contentRef), derivedFromOccurrenceId: null, language: '', derivationBasis: '' }); fileChoice.value = '' }
function roleChanged(item: DocumentContent) { if (!derived(item)) { item.derivedFromOccurrenceId = null; item.derivationBasis = '' } }
function removeContent(item: DocumentContent) { if (!body.value) return; if (body.value.contents.some(x => x.derivedFromOccurrenceId === item.occurrenceId)) { error.value = '请先移除依赖此原件的派生关系。'; return } body.value.contents = body.value.contents.filter(x => x.occurrenceId !== item.occurrenceId) }
async function save() {
  const s = scope.value, p = parent.value, draft = body.value; if (!s || !p?.draft.productRef || !draft || locked.value || !canWrite.value) return
  const saved = current.value, id = draftId.value, input = copy(draft); input.revisionOrigin = copy(p.reference); input.productRef = copy(p.draft.productRef); if (!input.source.sourceDate) input.source.sourceDate = null
  await run(async check => { await saveDocument(s, id, () => { check(); if (!canWrite.value) throw new Error('当前无文档写入权限。') }, operationId => documentApi.save({ operationId, documentId: id, action: saved ? 'REVISE' : 'CREATE', expectedVersion: saved?.reference.version ?? null, expectedEtag: saved?.etag ?? null, body: input, reason: reason.value })); check(); clearEditor(); await loadRows(1, check); notice.value = '文档工作版本已保存，仍待专业评审。' })
}
async function readHistory() { const v = current.value; if (!v) return; await run(async check => { history.value = null; const h = result(await documentApi.read(v.reference.id, historyVersion.value)); check(); history.value = h }) }
async function readDiff() { const v = current.value; if (!v) return; await run(async check => { diff.value = null; const d = result(await documentApi.diff(v.reference.id, before.value, after.value)); check(); diff.value = d }) }
async function download(v: DocumentSnapshot, occurrence: string) { await run(async check => { const member = v.body.contents.find(x => x.occurrenceId === occurrence); if (!member) throw new Error('缺少准确内容引用。'); const blob = await documentApi.download(v.reference.id, v.reference.version, occurrence); check(); const bytes = await blob.arrayBuffer(); check(); const digest = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))).map(x => x.toString(16).padStart(2, '0')).join(''); check(); if (bytes.byteLength !== member.file.byteLength || digest !== member.file.digest) throw new Error('下载内容与文档原版本不一致。'); const url = URL.createObjectURL(new Blob([bytes], { type: 'application/octet-stream' })); urls.add(url); const a = document.createElement('a'); a.href = url; a.download = v.contentStatus.find(x => x.occurrenceId === occurrence)?.fileName ?? 'document'; a.click(); window.setTimeout(() => { URL.revokeObjectURL(url); urls.delete(url) }, 1000) }) }
async function recover(close: boolean) { const s = scope.value; if (!s) return; await run(async check => { const value = await resolveDocument(s, close, check); check(); clearEditor(); rows.value = []; notice.value = value.state === 'COMMITTED' ? '原操作已提交，请重新读取文档。' : value.state === 'CLOSED' ? '未提交操作已结束。' : '原结果仍未知，请继续查询。' }) }
function clear() { generation++; busy.value = false; clearPrivate(); scope.value = null; pending.value = null; error.value = notice.value = '' }
function changed() { clear(); if (authenticationCanRead()) void reload() }
function storage(e: StorageEvent) { if (e.key?.startsWith('cp6_document_operation_v1:')) { try { syncPending() } catch { error.value = '原操作记录异常，请保留记录。' } } }
watch(choice, () => { clearEditor(); rows.value = [] }); watch(canRead, allowed => { if (!allowed) clear() })
onMounted(() => { window.addEventListener(AUTH_EVENT, changed); window.addEventListener('storage', storage); void reload() })
onBeforeUnmount(() => { live = false; generation++; clearPrivate(); window.removeEventListener(AUTH_EVENT, changed); window.removeEventListener('storage', storage) })
</script>
<style scoped>
.document-page{display:grid;gap:18px;padding:24px;color:var(--el-text-color-primary)}header,form,nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap}header{justify-content:space-between}section,article{padding:18px;border:1px solid var(--el-border-color);border-radius:8px;background:var(--el-bg-color)}article{margin:12px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}label{display:grid;gap:6px;margin:8px 0}input,select,textarea,button{font:inherit;padding:8px;border:1px solid var(--el-border-color);border-radius:4px;color:inherit;background:var(--el-bg-color);max-width:100%;box-sizing:border-box}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}fieldset{border:0;padding:0;width:100%}.digest{overflow-wrap:anywhere}[role=alert]{color:var(--el-color-danger)}:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}@media(max-width:600px){.document-page{padding:12px}section,article{padding:12px}}
</style>
